// Shapes of the database rows this app reads. Later you can replace these
// with types generated by Supabase (`npx supabase gen types typescript`).
import type { Role } from "@/lib/auth/roles";

export type OutletType = "restaurant" | "cafe" | "cloud_kitchen" | "qsr" | "bar" | "other";

export type Outlet = {
  id: string;
  org_id: string;
  name: string;
  code: string;
  outlet_type: OutletType;
  address_line1: string | null;
  address_line2: string | null;
  city: string | null;
  state: string | null;
  state_code: string | null;
  pincode: string | null;
  phone: string | null;
  email: string | null;
  gstin: string | null;
  fssai_no: string | null;
  logo_url: string | null;
  prices_include_tax: boolean;
  service_charge_enabled: boolean;
  service_charge_rate: number;
  day_start_hour: number;
  timezone: string;
  receipt_header: string | null;
  receipt_footer: string | null;
  printer_paper_width: 58 | 80;
  is_active: boolean;
  created_at: string;
};

export type OutletSummary = Pick<
  Outlet,
  "id" | "org_id" | "name" | "code" | "city" | "logo_url" | "day_start_hour" | "is_active"
>;

export type Organization = {
  id: string;
  name: string;
  owner_id: string;
  phone: string | null;
  email: string | null;
};

export type TaxGroup = {
  id: string;
  org_id: string;
  name: string;
  cgst_rate: number;
  sgst_rate: number;
  total_rate: number;
  is_default: boolean;
  is_active: boolean;
};

export type StaffMember = {
  id: string;
  org_id: string;
  user_id: string | null;
  full_name: string;
  role: Role;
  is_active: boolean;
};
